-- Canonical export recovered read-only from Staging migration history.
-- Version: 20260831075841; name: enterprise_management_summary

create or replace view public.enterprise_management_summary with (security_invoker=true) as select e.id as enterprise_id,coalesce(e.display_name,e.legal_name) as enterprise_name,(select count(*) from public.enterprise_service_requests r where r.enterprise_id=e.id and r.status not in ('completed','rejected','cancelled')) as active_cases,(select count(*) from public.enterprise_service_requests r where r.enterprise_id=e.id and r.next_action_due_at<now() and r.status not in ('completed','rejected','cancelled')) as overdue_cases,(select count(*) from public.enterprise_esg_assets a where a.enterprise_id=e.id and a.status='approved') as approved_outcomes,(select count(*) from public.enterprise_esg_delivery_readiness d where d.enterprise_id=e.id and d.delivery_ready) as deliverable_outcomes,(select count(distinct s) from public.enterprise_esg_assets a cross join lateral unnest(coalesce(a.sdg_tags,array[]::text[])) s where a.enterprise_id=e.id and a.status='approved') as sdg_coverage from public.enterprises e;
